// IMAGE EMBED
(function(){
  var b64='';
  var el=document.getElementById('heroBg');
  el.style.backgroundImage="url('data:image/jpeg;base64,"+b64+"')";
})();

// LOADER
window.addEventListener('load',function(){
  setTimeout(function(){document.getElementById('loader').classList.add('gone')},1200);
});

// NAV SCROLL
var nav=document.getElementById('navbar');
window.addEventListener('scroll',function(){
  nav.classList.toggle('scrolled',window.scrollY>60);
  // progress bar
  var pct=window.scrollY/(document.body.scrollHeight-window.innerHeight)*100;
  document.getElementById('progress').style.width=pct+'%';
  // parallax
  document.getElementById('heroBg').style.transform='translateY('+(window.scrollY*.35)+'px)';
  // reveal
  document.querySelectorAll('.reveal').forEach(function(el){
    if(el.getBoundingClientRect().top<window.innerHeight-60) el.classList.add('visible');
  });
},{passive:true});
// trigger once
window.dispatchEvent(new Event('scroll'));

// MOBILE MENU
function toggleMobile(){
  document.getElementById('mobileMenu').classList.toggle('open');
}

// LIGHTBOX
var galleryImgs=['🏨','🍛','🍗','🦐','🍮'];
function openLb(i){
  document.getElementById('lightbox').classList.add('open');
}
function closeLb(){document.getElementById('lightbox').classList.remove('open');}
document.addEventListener('keydown',function(e){if(e.key==='Escape')closeLb();});

// TESTIMONIAL SLIDER
var cur=0,total=3;
function goSlide(n){
  cur=n;
  document.getElementById('testiTrack').style.transform='translateX(-'+(n*100)+'%)';
  document.querySelectorAll('.testi-dot').forEach(function(d,i){d.classList.toggle('active',i===n);});
}
function nextSlide(){goSlide((cur+1)%total);}
function prevSlide(){goSlide((cur-1+total)%total);}
setInterval(nextSlide,5000);
